/**
 * Random "segment names" shared by the shell (app.js) and the confirmation frame (confirm-frame.js).
 * Every load of either document draws new values, so no tag, id, class or test id survives a reload.
 */
const ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';

/** Five random letters or digits. */
export const rand = () => Array.from(crypto.getRandomValues(new Uint8Array(5)), (b) => ALPHABET[b % 36]).join('');

/** A custom-element tag name: mf-<rand>-<rand>. */
export const tagName = () => `mf-${rand()}-${rand()}`;

/** An id that starts with a letter, as ids generated by frameworks do. */
export const newId = () => `${ALPHABET[Math.floor(Math.random() * 26)]}${rand()}${rand()}`;

/** A CSS-in-JS style class. */
export const cls = (prefix = 'css') => `${prefix}-${rand()}`;

/** A generated test id, like the PDF's data-test-id="dyn-uuid-9921". */
export const testId = () => `dyn-uuid-${1000 + (crypto.getRandomValues(new Uint16Array(1))[0] % 9000)}`;

/** Wraps markup in 0-2 anonymous divs, so absolute paths change from load to load. */
export const wrap = (html) => {
  let out = html;
  for (let depth = Math.floor(Math.random() * 3); depth > 0; depth--) out = `<div class="${cls()}">${out}</div>`;
  return out;
};
